<script setup lang="ts">
import Select from '../components/ui/Select.vue'
import { computed,onMounted,onUnmounted,ref,watch } from 'vue'
import { api,hasRole } from '../api'
import { useLoad,time } from '../composables'
import { useWorkspace } from '../stores/workspace'
import { healthSegments,eventBuckets,latencySamples,scopedResult } from '../presentation'
import type { Overview,Page,Incident,CheckRun } from '../types'
import StatusBadge from '../components/StatusBadge.vue'
import PageState from '../components/PageState.vue'
import AppIcon from '../components/AppIcon.vue'
import Button from '../components/ui/Button.vue'
import DataChart from '../components/DataChart.vue'
import LiveIndicator from '../components/LiveIndicator.vue'
type Activity={from:string;to:string;bucket:string;points:{time:string;count:number}[];total:number}
const workspace=useWorkspace(),target=ref('')
const {data,loading,error,load}=useLoad(()=>api<Overview>('/overview'))
const events=useLoad(async()=>{const scope=workspace.range,window=workspace.windowQuery();const [activity,incidents]=await Promise.all([api<Activity>('/workspace/activity?'+window),api<Page<Incident>>('/workspace/incidents?size=5&'+window)]);return {scope,value:{activity,incidents}}})
const history=useLoad(async()=>{const scope=target.value;return {scope,value:scope?await api<Page<CheckRun>>('/targets/'+scope+'/checks/history?size=100'):null}})
const currentEvents=computed(()=>scopedResult(events.data.value,workspace.range)),currentHistory=computed(()=>scopedResult(history.data.value,target.value))
const segments=computed(()=>data.value?healthSegments(data.value):[]),buckets=computed(()=>currentEvents.value?eventBuckets(currentEvents.value.activity):[])
const latency=computed(()=>{const to=currentEvents.value?.activity.to,from=currentEvents.value?.activity.from;return to&&from?latencySamples(currentHistory.value?.items||[],Date.parse(from),Date.parse(to)):[]})
watch(target,()=>void history.load());watch(()=>workspace.range,()=>void events.load())
async function refresh(){await Promise.all([load(),events.load(),target.value?history.load():Promise.resolve()])}
watch(data,value=>{if(value&&!target.value)target.value=value.targets[0]?.id||''})
onMounted(refresh);const timer=setInterval(()=>{if(!document.hidden&&!loading.value&&!events.loading.value)void refresh()},30000);onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><div class="eyebrow">Operations overview</div><h1>运维总览</h1><p>先看服务健康，再定位需要处理的事件。</p></div><div class="actions"><LiveIndicator :seconds="30" :loading="loading" :updated="data?.generatedAt" /><Button variant="outline" :disabled="loading" @click="refresh"><AppIcon name="refresh" :size="15" />刷新</Button></div></div>
<PageState :loading="loading&&!data" :error="error" @retry="refresh"><template v-if="data"><div class="summary-strip"><div><span><AppIcon name="target" :size="15" />服务目标</span><strong>{{ data.totalTargets }}</strong><small>{{ data.activeChecks }} 项有效检查 · 当前快照</small></div><div><span><AppIcon name="check" :size="15" />运行正常</span><strong class="good">{{ data.up }}</strong><small>最新检查证据仍在有效期内</small></div><div><span><AppIcon name="incident" :size="15" />服务异常</span><strong :class="data.down?'danger':''">{{ data.down }}</strong><small>{{ data.unknown }} 个未知 · 不计为正常</small></div><div><span><AppIcon name="clock" :size="15" />活动事故</span><strong :class="data.activeIncidents?'warning':''">{{ data.activeIncidents }}</strong><small>当前未关闭的处置记录</small></div></div>
<div class="dashboard-canvas"><section class="panel chart-panel"><div class="panel-heading"><div><h2>事件发生趋势</h2><p>{{ workspace.rangeLabel }} · 按首次发现时间统计</p></div><span v-if="currentEvents" class="heading-count">{{ currentEvents.activity.total }} 起</span></div><PageState :loading="events.loading.value&&!currentEvents" :error="events.error.value" @retry="events.load"><DataChart kind="events" :points="buckets" :label="'事件发生趋势，共 '+(currentEvents?.activity.total||0)+' 起；'+workspace.rangeLabel" /></PageState><div class="panel-footnote">全量可见事件聚合 · 首尾时间桶可能不完整 · 不表示告警频率</div></section><section class="panel"><div class="panel-heading"><h2>服务健康分布</h2><span class="env-tag">当前快照</span></div><DataChart kind="health" :segments="segments" :label="'正常 '+data.up+' 个，异常 '+data.down+' 个，未知 '+data.unknown+' 个'" compact /><div class="chart-legend"><span class="good">正常 {{ data.up }}</span><span class="danger">异常 {{ data.down }}</span><span class="muted">未知 {{ data.unknown }}</span></div><div class="panel-footnote">未知包含无检查、暂停检查与证据过期的目标</div></section></div>
<div class="overview-columns"><section class="panel"><div class="panel-heading"><div><h2>检查响应时间</h2><p>最近 100 条检查中位于所选时间范围内的实际样本</p></div><label><span class="sr-only">图表服务目标</span><Select v-model="target" aria-label="图表服务目标" :options="data.targets.length?data.targets.map(t=>({value:t.id,label:t.name})):[{value:'',label:'暂无服务'}]" /></label></div><PageState :loading="history.loading.value&&!currentHistory" :error="history.error.value" @retry="history.load"><DataChart kind="latency" :points="latency" :label="'检查延迟，'+latency.length+' 条样本，单位毫秒；未知结果保留缺口'" /></PageState><div class="panel-footnote">{{ latency.length }} 条窗口内样本 · 未知结果保留缺口 · 仅可选择当前概览展示的最多 20 个目标</div></section><section class="panel"><div class="panel-heading"><h2>最近事件</h2><RouterLink to="/incidents" class="text-link">事件中心<AppIcon name="chevron" :size="14" /></RouterLink></div><PageState :loading="events.loading.value&&!currentEvents" :error="events.error.value" :empty="!!currentEvents&&!currentEvents.incidents.items.length" title="所选时间内没有事件" description="检查连续失败达到阈值后，事件将自动进入队列。" @retry="events.load"><div class="incident-preview-list"><RouterLink v-for="i in currentEvents?.incidents.items" :key="i.id" :to="'/incidents/'+i.id" class="incident-preview"><div><span class="severity">{{ i.severity }}</span><StatusBadge :value="i.status" /></div><strong>{{ i.targetName }}</strong><p>{{ i.summary }}</p><small>{{ time(i.openedAt) }}</small></RouterLink></div></PageState></section></div>
<section class="panel" style="margin-top:24px"><div class="panel-heading"><h2>服务状态清单</h2><RouterLink to="/targets" class="text-link">全部服务<AppIcon name="chevron" :size="14" /></RouterLink></div><PageState :empty="!data.targets.length" title="从第一个服务开始" description="登记健康检查地址并启用检查，服务状态就会出现在这里。"><template #action><RouterLink v-if="hasRole('OPS_ADMIN')" to="/targets/new" class="btn primary">登记服务目标</RouterLink></template><div class="table-scroll"><table><thead><tr><th>服务</th><th>环境</th><th>当前状态</th><th>最近检查</th></tr></thead><tbody><tr v-for="t in data.targets" :key="t.id"><td><RouterLink :to="'/targets/'+t.id" class="row-title">{{ t.name }}</RouterLink><small class="cell-note mono">{{ t.code }}</small></td><td><span class="env-tag">{{ t.environment }}</span></td><td><StatusBadge :value="t.health" /></td><td class="timestamp">{{ time(t.lastCheckedAt) }}</td></tr></tbody></table></div></PageState></section><div class="data-caption">快照更新于 {{ time(data.generatedAt) }} · 范围筛选仅影响事件趋势、最近事件与检查图表</div></template></PageState></template>
